Algorithm ModularPhaseLockingDetector(a, b, P):
  // Step 1: Detect spectral torsion
  if a == 1: m = 1
  elif a == -1: m = 2
  else: m = None (no integer torsion)

  // Step 2: Check geometric sum condition
  if m is not None:
    S = sum(a^k for k in 0..m-1)
    if S * b == 0: LOCKED with period m
    else: NOT LOCKED

  // Step 3: Empirical verification
  for each prime p <= P:
    Compute orbit of 0 under T(y) = a*y + b mod p
    Record (preperiod, period)
    Verify period divides m if LOCKED

  // Theorem guarantee: if LOCKED, period divides m for ALL primes
  // (by spectral_torsion_modp_1d)
